@extends('layouts.app') @section('content')<div class="page-head"><div><p class="eyebrow">EXAM BUILDER</p><h1>{{$exam->exists?'Edit examination':'Create examination'}}</h1></div></div><form class="panel form-grid" method="post" action="{{$exam->exists?route('exams.update',$exam):route('exams.store')}}">@csrf @if($exam->exists) @method('PUT') @endif<label class="wide">Title<input name="title" value="{{old('title',$exam->title)}}" required maxlength="180"></label><label class="wide">Description<textarea name="description" rows="4">{{old('description',$exam->description)}}</textarea></label><label>Duration (minutes)<input type="number" name="duration_minutes" value="{{old('duration_minutes',$exam->duration_minutes?:30)}}" min="1" max="600" required></label><label>Starts at<input type="datetime-local" name="starts_at" value="{{old('starts_at',$exam->starts_at?->format('Y-m-d\\TH:i'))}}"></label><label>Ends at<input type="datetime-local" name="ends_at" value="{{old('ends_at',$exam->ends_at?->format('Y-m-d\\TH:i'))}}"></label><label class="check wide"><input type="checkbox" name="is_published" value="1" {{$exam->is_published?'checked':''}}> Publish exam</label>@if(auth()->user()->isAdmin())<label class="check"><input type="checkbox" name="allow_retake" value="1" {{$exam->allow_retake?'checked':''}}> Allow student retakes</label><label>Maximum attempts (blank = unlimited)<input type="number" name="attempt_limit" min="2" max="100" value="{{old('attempt_limit',$exam->attempt_limit)}}" {{$exam->allow_retake?'':'disabled'}}></label>@endif<div class="wide actions"><button class="btn primary">Save examination</button><a class="btn ghost" href="{{route('exams.index')}}">Cancel</a></div></form>@if($exam->exists)<form class="danger-zone" method="post" action="{{route('exams.destroy',$exam)}}">@csrf @method('DELETE')<button class="btn danger">Delete examination</button></form>@endif<script>document.addEventListener('DOMContentLoaded',()=>{const c=document.querySelector('[name=allow_